const SITE="Biblioteca de Alexandria";
// Preencha para ativar os e-mails (veja o comentário no topo do arquivo).
const EJ={service:"SEU_SERVICE_ID",welcome:"SEU_TEMPLATE_ID",reset:"SEU_TEMPLATE_RECUPERACAO_ID",key:"SUA_PUBLIC_KEY"};

const $=id=>document.getElementById(id);
const esc=s=>String(s??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
const K={books:"resenha_livros",ses:"resenha_sessao",users:"resenha_usuarios",com:"farol_comunidade_v1"};
const read=(k,d)=>{try{return JSON.parse(localStorage.getItem(k))??d}catch(e){return d}};
const write=(k,v)=>{try{localStorage.setItem(k,JSON.stringify(v))}catch(e){alert("Não foi possível salvar: armazenamento local cheio ou bloqueado.")}};
const ses=()=>read(K.ses,null), users=()=>read(K.users,[]), me=()=>ses()?.email||null;
const isEmail=v=>/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v);
const fmt=t=>t?new Date(t).toLocaleDateString("pt-BR",{day:"2-digit",month:"short",year:"numeric"}):"agora";
const norm=t=>String(t||"").toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g,"").replace(/[^a-z0-9]+/g," ").trim();
const stars=v=>`<span class="stars" style="--p:${Math.min(100,(v||0)*20)}%"></span>`;

// ---------- E-mail (EmailJS carregado só quando configurado) ----------
const mailOn=t=>![EJ.service,EJ[t],EJ.key].some(v=>/^SE?U/.test(v));
function sendMail(t,p){return new Promise((ok,no)=>{
  const go=()=>emailjs.send(EJ.service,EJ[t],{...p,site_name:SITE},{publicKey:EJ.key}).then(ok,no);
  if(window.emailjs)return go();
  const s=document.createElement("script");s.src="https://cdn.jsdelivr.net/npm/@emailjs/browser@4/dist/email.min.js";s.onload=go;s.onerror=no;document.head.append(s);});}

// ---------- Páginas ----------
let page="livros",detId=null;
function show(p){page=p;["livros","conta","detalhe"].forEach(n=>$("page-"+n).classList.toggle("active",n===p));topLink();scrollTo(0,0)}
function topLink(){const s=ses();$("top-link").textContent=page==="livros"?(s?`Olá, ${s.nome} · Sair`:"Entrar / Criar conta"):page==="conta"?"← Voltar":"← Voltar aos livros";$("livro-usuario").value=s?s.nome:""}
$("top-link").onclick=e=>{e.preventDefault();if(page==="livros"&&ses()){localStorage.removeItem(K.ses);topLink();renderAll()}else show(page==="livros"?"conta":"livros")};
$("brand").onclick=()=>show("livros");
function view(v){document.querySelectorAll("#tabs button").forEach(b=>b.classList.toggle("active",b.dataset.v===v));document.querySelectorAll(".view").forEach(x=>x.classList.toggle("active",x.id==="v-"+v));renderAll()}
$("tabs").onclick=e=>{const b=e.target.closest("button");if(b)view(b.dataset.v)};

// ---------- Conta ----------
function panel(w){["login","signup","recuperar"].forEach(n=>$("panel-"+n).classList.toggle("active",n===w));$("tab-login").classList.toggle("active",w!=="signup");$("tab-signup").classList.toggle("active",w==="signup");document.querySelectorAll(".status").forEach(s=>s.classList.remove("show"))}
$("page-conta").addEventListener("click",e=>{const b=e.target.closest("[data-p]");if(b){e.preventDefault();panel(b.dataset.p)}});
$("esqueci").onclick=e=>{e.preventDefault();panel("recuperar")};
function err(id,on,msg){const f=$(id);f.classList.toggle("error",!!on);if(msg)f.querySelector(".msg").textContent=msg}
const setSes=u=>write(K.ses,{nome:u.nome,email:u.email});
const home=ms=>setTimeout(()=>{show("livros");renderAll()},ms);

$("form-login").onsubmit=e=>{e.preventDefault();
  const em=$("login-email").value.trim().toLowerCase(),pw=$("login-senha").value;
  err("f-login-email",!isEmail(em));err("f-login-senha",!pw,"Informe sua senha.");
  if(!isEmail(em)||!pw)return;
  const u=users().find(x=>x.email===em);
  if(!u||u.senha!==pw)return err("f-login-senha",true,"E-mail ou senha incorretos.");
  setSes(u);$("status-login").classList.add("show");home(700);};

$("form-recuperar").onsubmit=e=>{e.preventDefault();
  const em=$("rec-email").value.trim().toLowerCase(),st=$("status-rec"),say=t=>{st.textContent=t;st.classList.add("show")};
  err("f-rec-email",!isEmail(em));if(!isEmail(em))return;
  const all=users(),u=all.find(x=>x.email===em),neutra="Se esse e-mail estiver cadastrado, enviamos uma nova senha para ele.";
  if(!u)return say(neutra);
  if(!mailOn("reset"))return say("O envio de e-mail ainda não foi configurado neste site. A senha não foi alterada.");
  say("Enviando nova senha...");
  const nova=String(Math.floor(Math.random()*1e6)).padStart(6,"0");
  sendMail("reset",{to_email:u.email,to_name:u.nome,nova_senha:nova})
    .then(()=>{u.senha=nova;write(K.users,all);say(neutra)})
    .catch(()=>say("Localizamos a conta, mas não foi possível enviar o e-mail agora. Tente novamente em instantes."));};

$("form-signup").onsubmit=e=>{e.preventDefault();
  const nome=$("su-nome").value.trim(),em=$("su-email").value.trim().toLowerCase(),pw=$("su-senha").value,cf=$("su-conf").value;
  const ok=[nome,isEmail(em),pw.length>=8,cf===pw&&pw.length>=8];
  err("f-su-nome",!ok[0]);err("f-su-email",!ok[1],"Informe um e-mail válido.");err("f-su-senha",!ok[2]);err("f-su-conf",!ok[3]);
  if(ok.includes(false)||ok.includes(""))return;
  const all=users();
  if(all.some(u=>u.email===em))return err("f-su-email",true,"Já existe uma conta com este e-mail. Tente entrar.");
  const u={nome,email:em,senha:pw};all.push(u);write(K.users,all);setSes(u);
  const st=$("status-signup"),fim=t=>{st.textContent=t;st.classList.add("show");home(1200)};
  if(!mailOn("welcome"))return fim("Conta criada com sucesso.");
  fim("Conta criada. Enviando e-mail de confirmação...");
  sendMail("welcome",{to_email:em,to_name:nome}).then(()=>st.textContent="Conta criada com sucesso. Enviamos uma confirmação para "+em+".").catch(()=>st.textContent="Conta criada, mas o e-mail de confirmação falhou.");};

// ---------- Dados ----------
const SEED_BOOKS = [{"id": "confissoes", "titulo": "Confissões — Santo Agostinho", "imagem": "data:image/jpeg;base64,"}, {"id": "cidade_de_deus", "titulo": "A Cidade de Deus — Santo Agostinho", "imagem": "data:image/jpeg;base64,"}, {"id": "iliada", "titulo": "Ilíada — Homero", "imagem": "data:image/jpeg;base64,"}, {"id": "hamlet", "titulo": "Hamlet — William Shakespeare", "imagem": "data:image/jpeg;base64,"}, {"id": "noites_brancas", "titulo": "Noites Brancas — Dostoiévski", "imagem": "data:image/jpeg;base64,"}, {"id": "kant", "titulo": "Crítica da Razão Pura — Kant", "imagem": "data:image/jpeg;base64,"}, {"id": "manifesto", "titulo": "O Manifesto Comunista — Marx e Engels", "imagem": "data:image/jpeg;base64,"}, {"id": "alquimista", "titulo": "O Alquimista — Paulo Coelho", "imagem": "data:image/jpeg;base64,"}, {"id": "odisseia", "titulo": "Odisseia — Homero", "imagem": "data:image/jpeg;base64,"}];
const def=()=>({status:"Lido",nota:0,favorito:false,likes:0,comentarios:[],tags:[],generos:[],createdAt:Date.now()});
let books=(read(K.books,null)||SEED_BOOKS).map(b=>({...def(),...b}));
const saveBooks=()=>write(K.books,books);
saveBooks();
const com=Object.assign({profiles:{},following:{},quotes:{},lists:{},readingLog:{}},read(K.com,{}));
const saveCom=()=>write(K.com,com);
const find=id=>books.find(b=>b.id===id);
let editing=null,newRating=5,cover=null;

// ---------- Cartões ----------
function card(b,shelf){
  const id=b.id,mine=shelf;
  const rev=!shelf?"":editing===id
    ?`<div class="edit"><textarea id="ed-${id}">${esc(b.resenha)}</textarea><div class="row"><button class="btn" data-a="save" data-id="${id}">Salvar</button><button class="link" data-a="cancel">Cancelar</button></div></div>`
    :`<div class="snip" data-a="expand">${esc(b.resenha||"Sem resenha ainda.")}</div><button class="link" data-a="edit" data-id="${id}">${b.resenha?"Editar resenha":"Escrever resenha"}</button>`;
  return `<article class="card"><button class="x" title="Remover" data-a="remove" data-id="${id}">&times;</button>
  <div class="cover" data-a="open" data-id="${id}"><img loading="lazy" decoding="async" src="${b.imagem}" alt="${esc(b.titulo)}"></div>
  <h3 data-a="open" data-id="${id}">${esc(b.titulo)}</h3><div class="meta">${esc(b.usuarioNome||"Leitor anônimo")}</div>
  <div class="row">${stars(Number(b.nota))}<span class="pill">${esc(b.status)}</span><button class="link" style="font-size:16px;color:${b.favorito?"var(--acc)":"var(--mute)"}" data-a="fav" data-id="${id}" title="Favoritar">${b.favorito?"★":"☆"}</button></div>${rev}</article>`;
}
function review(b){
  const em=me(),seguindo=(com.following[em]||[]).includes(b.usuarioEmail),outro=em&&b.usuarioEmail&&b.usuarioEmail!==em;
  return `<div class="box${b.spoiler?" spoiler":""}"><div class="row" style="margin:0"><div class="avatar">${esc((b.usuarioNome||"L")[0].toUpperCase())}</div><div><b style="font-size:13px">${esc(b.usuarioNome||"Leitor")}</b><div class="meta">${fmt(b.createdAt)}</div></div></div>
  <div style="margin-top:8px">${stars(Number(b.nota))}</div><div class="txt">${esc(b.resenha||"Sem resenha escrita.")}</div>
  <div class="acts"><button data-a="like" data-id="${b.id}">♥ ${b.likes||0}</button><button data-a="comment-focus" data-id="${b.id}">Comentar</button><button data-a="spoiler" data-id="${b.id}">Spoiler</button>${outro?`<button data-a="follow" data-id="${esc(b.usuarioEmail)}">${seguindo?"Seguindo":"Seguir"}</button>`:""}</div>
  <div class="comments">${(b.comentarios||[]).map(c=>`<div><b>${esc(c.nome)}</b>: ${esc(c.texto)}</div>`).join("")}</div>
  <div class="inline"><input id="ci-${b.id}" placeholder="Escreva um comentário..."><button class="btn" data-a="comment" data-id="${b.id}">Enviar</button></div></div>`;
}

// ---------- Renderização ----------
function renderShelf(){
  const q=$("busca").value.trim().toLowerCase(),f=$("filtro").value,o=$("ordem").value;
  let l=books.filter(b=>(!q||b.titulo.toLowerCase().includes(q))&&(f==="todos"||b.status===f));
  l.sort((a,b)=>o==="titulo"?a.titulo.localeCompare(b.titulo):o==="nota"?b.nota-a.nota:o==="favoritos"?b.favorito-a.favorito:b.createdAt-a.createdAt);
  $("count").textContent=l.length+(l.length===1?" livro":" livros");
  $("shelf").innerHTML=l.map(b=>card(b,true)).join("")||'<p class="mute">Nenhum livro encontrado.</p>';
}
function renderExplore(){
  const q=$("ex-busca").value.toLowerCase().trim(),o=$("ex-ordem").value;
  const l=books.filter(b=>!q||(b.titulo+" "+(b.usuarioNome||"")+" "+b.tags.join(" ")).toLowerCase().includes(q));
  l.sort((a,b)=>o==="avaliados"?b.nota-a.nota:o==="recentes"?b.createdAt-a.createdAt:b.likes-a.likes);
  $("ex-res").innerHTML=l.map(b=>card(b)).join("")||'<p class="mute">Nenhum resultado encontrado.</p>';
  $("destaques").innerHTML=[...books].sort((a,b)=>b.likes-a.likes).slice(0,5).map(review).join("")||'<p class="mute">Ainda não há resenhas em destaque.</p>';
}
function renderFeed(){
  const f=com.following[me()]||[];
  $("feed-list").innerHTML=books.filter(b=>f.includes(b.usuarioEmail)).sort((a,b)=>b.createdAt-a.createdAt).slice(0,30)
    .map(b=>`<div class="box"><b>${esc(b.usuarioNome||"Leitor")}</b> adicionou <b>${esc(b.titulo)}</b> à estante · ${esc(b.status)}<div class="meta">${fmt(b.createdAt)}</div></div>`).join("")||'<p class="mute">Seu feed está vazio. Siga leitores para acompanhar suas atividades.</p>';
}
function renderProfile(){
  const em=me(),u=users().find(x=>x.email===em);
  if(!u){$("perfil-card").innerHTML='<p class="mute">Entre em sua conta para personalizar seu perfil.</p>';$("diario").innerHTML=$("citacoes").innerHTML="";return}
  const mine=books.filter(b=>b.usuarioEmail===em),bio=(com.profiles[em]||{}).bio||"Leitor da "+SITE+".";
  const seg=Object.values(com.following).filter(a=>(a||[]).includes(em)).length;
  const st=[[mine.filter(b=>b.status==="Lido").length,"livros lidos"],[mine.filter(b=>b.favorito).length,"favoritos"],[seg,"seguidores"],[(com.following[em]||[]).length,"seguindo"]];
  $("perfil-card").innerHTML=`<div class="row" style="margin:0"><div class="avatar">${esc(u.nome[0].toUpperCase())}</div><div><h2>${esc(u.nome)}</h2><div class="meta">${esc(bio)}</div></div></div>
    <div class="stats" style="margin:14px 0">${st.map(x=>`<div class="stat"><b>${x[0]}</b><span class="meta">${x[1]}</span></div>`).join("")}</div>
    <div class="inline"><input id="bio-input" value="${esc(bio)}" maxlength="180"><button class="btn" data-a="bio">Salvar bio</button></div>`;
  const qs=com.quotes[em]||[],lg=com.readingLog[em]||[];
  $("citacoes").innerHTML=qs.map(q=>`<div class="box">“${esc(q)}”</div>`).join("")||'<p class="mute">Nenhuma citação salva.</p>';
  $("diario").innerHTML=lg.slice().reverse().map(l=>`<div class="log"><b>${esc(l.titulo)}</b><div class="meta">${esc(l.nota||"")} · ${fmt(l.data)}</div></div>`).join("")||'<p class="mute">Seu diário aparecerá conforme você registrar leituras.</p>';
}
function renderStats(){
  const mine=books.filter(b=>b.usuarioEmail===me()),lidos=mine.filter(b=>b.status==="Lido"),notas=lidos.map(b=>+b.nota).filter(n=>n>0),
    media=notas.length?(notas.reduce((a,b)=>a+b,0)/notas.length).toFixed(1):"—",res=mine.filter(b=>b.resenha).length,fav=mine.filter(b=>b.favorito).length,
    gen=new Set(mine.flatMap(b=>b.generos)).size,pag=mine.reduce((s,b)=>s+Number(b.paginas||0),0);
  $("stats").innerHTML=[["Livros lidos",lidos.length],["Páginas",pag],["Nota média",media],["Favoritos",fav],["Gêneros",gen],["Resenhas",res]].map(x=>`<div class="box stat"><b>${x[1]}</b><span class="meta">${x[0]}</span></div>`).join("");
  $("recap").innerHTML=`<p class="mute" style="margin:0">Em ${new Date().getFullYear()}, você registrou <b>${lidos.length}</b> livro(s) lido(s), escreveu <b>${res}</b> resenha(s) e deu nota média <b>${media}</b>.</p>`;
  const a=[[lidos.length>=1,"Primeira leitura registrada"],[lidos.length>=5,"5 livros lidos"],[res>=3,"Crítico em formação"],[fav>=3,"Colecionador de favoritos"]].filter(x=>x[0]);
  $("conquistas").innerHTML=a.map(x=>`<span class="pill" style="margin:0 6px 6px 0">${x[1]}</span>`).join("")||'<p class="mute">Suas primeiras conquistas aparecerão aqui.</p>';
}
function renderLists(){
  const l=com.lists[me()]||[];
  $("listas").innerHTML=l.map(x=>`<div class="box"><b>${esc(x.nome)}</b><div class="meta">${x.livros.length} livro(s) · lista pessoal</div></div>`).join("")||'<p class="mute">Crie uma lista para organizar leituras por tema, autor ou momento.</p>';
}
function renderDetail(){
  const b=find(detId);if(!b)return;
  const g=books.filter(x=>norm(x.titulo)===norm(b.titulo)),n=g.map(x=>+x.nota).filter(v=>v>0),m=n.length?n.reduce((a,c)=>a+c,0)/n.length:0;
  $("d-cover").src=b.imagem;$("d-cover").alt=b.titulo;$("d-titulo").textContent=b.titulo;$("d-usuario").textContent=b.usuarioNome||"Leitor anônimo";
  $("d-resenha").textContent=b.resenha||"Ainda sem resenha para este livro.";
  $("d-meta").innerHTML=`<div class="row">${stars(m)}<span class="meta">${m?m.toFixed(1):"—"} / 5 · ${g.length} resenha(s)</span><span class="pill">${esc(b.status)}</span></div>`;
  $("d-reviews").innerHTML='<h2 class="sec">Resenhas da comunidade</h2>'+g.map(review).join("");
}
function renderRating(){$("new-rating").innerHTML=[1,2,3,4,5].map(i=>`<button type="button" class="${i<=newRating?"on":""}" data-a="rate" data-n="${i}">★</button>`).join("")}
function renderAll(){renderShelf();renderExplore();renderFeed();renderProfile();renderStats();renderLists();if(page==="detalhe")renderDetail()}

// ---------- Ações ----------
const actions={
  open:id=>{detId=id;renderDetail();show("detalhe")},
  fav:id=>{const b=find(id);b.favorito=!b.favorito;saveBooks();renderAll()},
  remove:id=>{books=books.filter(b=>b.id!==id);saveBooks();renderAll()},
  edit:id=>{editing=id;renderShelf();$("ed-"+id)?.focus()},
  cancel:()=>{editing=null;renderShelf()},
  save:id=>{find(id).resenha=$("ed-"+id).value.trim();editing=null;saveBooks();renderAll()},
  like:id=>{const b=find(id),e=me()||"anonimo";b._likedBy=b._likedBy||[];const i=b._likedBy.indexOf(e);
    if(i>=0){b._likedBy.splice(i,1);b.likes=Math.max(0,b.likes-1)}else{b._likedBy.push(e);b.likes++}saveBooks();renderAll()},
  spoiler:id=>{const b=find(id);b.spoiler=!b.spoiler;saveBooks();renderAll()},
  follow:email=>{const e=me();if(!e)return;const a=com.following[e]=com.following[e]||[],i=a.indexOf(email);i>=0?a.splice(i,1):a.push(email);saveCom();renderAll()},
  comment:id=>{const i=$("ci-"+id),t=i.value.trim();if(!t)return;find(id).comentarios.push({nome:ses()?.nome||"Leitor",texto:t,data:Date.now()});saveBooks();renderAll()},
  "comment-focus":id=>{const i=$("ci-"+id);i.focus();i.scrollIntoView({behavior:"smooth",block:"center"})},
  bio:()=>{const e=me();if(!e)return;com.profiles[e]={...com.profiles[e],bio:$("bio-input").value.trim()};saveCom();renderProfile()},
  rate:(_,t)=>{newRating=+t.dataset.n;renderRating()}
};
document.addEventListener("click",e=>{
  const t=e.target.closest("[data-a]");if(!t)return;
  if(t.dataset.a==="expand")return t.classList.toggle("open");
  actions[t.dataset.a]?.(t.dataset.id,t);
});
["busca","filtro","ordem"].forEach(i=>$(i).addEventListener("input",renderShelf));
["ex-busca","ex-ordem"].forEach(i=>$(i).addEventListener("input",renderExplore));
$("add-quote").onclick=()=>{const e=me(),i=$("quote-input");if(!e||!i.value.trim())return;(com.quotes[e]=com.quotes[e]||[]).push(i.value.trim());i.value="";saveCom();renderProfile()};
$("create-list").onclick=()=>{const e=me(),i=$("list-name");if(!e||!i.value.trim())return;(com.lists[e]=com.lists[e]||[]).push({nome:i.value.trim(),livros:[]});i.value="";saveCom();renderLists()};

// ---------- Novo livro ----------
$("livro-imagem").onchange=e=>{const f=e.target.files[0];if(!f)return;const r=new FileReader();
  r.onload=x=>{cover=x.target.result;$("preview").src=cover;$("upload").classList.add("has")};r.readAsDataURL(f)};
$("form-add").onsubmit=e=>{e.preventDefault();
  const titulo=$("livro-titulo").value.trim(),st=$("status-add"),s=ses();
  st.classList.add("show");
  if(!titulo||!cover){st.textContent="Escolha uma capa e informe o título do livro.";return}
  books.push({...def(),id:crypto.randomUUID?crypto.randomUUID():Date.now()+""+Math.random(),titulo,imagem:cover,resenha:$("livro-resenha").value.trim(),
    usuarioNome:s?.nome||"Leitor anônimo",usuarioEmail:s?.email||null,status:$("livro-status").value,nota:newRating});
  saveBooks();renderAll();
  st.textContent=`"${titulo}" foi adicionado à sua estante.`;
  $("livro-titulo").value=$("livro-resenha").value=$("livro-imagem").value="";cover=null;$("preview").src="";$("upload").classList.remove("has");
};

renderRating();topLink();renderAll();
